const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Victoria and Corpus Christi, Texas
  const victoria = ee.Geometry.Point([-97.003, 28.805]);
  const corpusChristi = ee.Geometry.Point([-97.396, 27.801]);

  // Buffer by 5km to get area around each city
  const victoriaArea = victoria.buffer(5000);
  const corpusChristiArea = corpusChristi.buffer(5000);

  // 2. Define time period: June 15 to June 22, 2018 (inclusive)
  const startDate = '2018-06-15';
  const endDate = '2018-06-23'; // Exclusive end date

  // 3. Load GPM IMERG precipitation data (mm/hour)
  const gpmCol = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .select('precipitation');

  // Check if collection is empty
  const count = gpmCol.size().getInfo();
  if (count === 0) {
    console.log(`GPM Images: ${count}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Convert mm/hour to total mm over period
  // Each image represents precipitation rate in mm/hour
  // Multiply by 24 to get mm/day, then sum over the period
  const precipitationSum = gpmCol.sum().multiply(24);

  // 5. Extract precipitation values for both cities
  const extractPrecip = function(geometry, name) {
    // First check for valid pixels
    const pixelCount = precipitationSum.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 10000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    if (pixelCount === 0) {
      console.log(`${name}: No valid pixels`);
      return null;
    }

    // Get mean precipitation in mm
    const precipMm = precipitationSum.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 10000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    // Convert mm to inches (1 inch = 25.4 mm)
    const precipInches = precipMm / 25.4;

    console.log(`${name}: ${precipMm.toFixed(1)} mm (${precipInches.toFixed(1)} inches), Pixels: ${pixelCount}`);

    return precipInches;
  };

  // 6. Extract precipitation for both cities
  const victoriaPrecip = extractPrecip(victoriaArea, "Victoria");
  const corpusPrecip = extractPrecip(corpusChristiArea, "Corpus Christi");

  // 7. Check for C2 (no valid pixels)
  if (victoriaPrecip === null || corpusPrecip === null) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 8. Validate results (C3 check)
  // Precipitation should be reasonable: between 0 and 1000 mm for 8 days
  // 1000 mm in 8 days would be extreme flooding
  if (victoriaPrecip * 25.4 > 1000 || corpusPrecip * 25.4 > 1000 ||
      victoriaPrecip * 25.4 < 0 || corpusPrecip * 25.4 < 0 ||
      isNaN(victoriaPrecip) || isNaN(corpusPrecip)) {
    console.log(`Validation failed: Victoria=${victoriaPrecip}, Corpus Christi=${corpusPrecip}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // 9. Check condition: BOTH cities must have <20 inches
  const bothLessThan20 = victoriaPrecip < 20 && corpusPrecip < 20;

  // 10. Output final answer
  console.log(`GPM Images: ${count}`);
  console.log(`Condition: Victoria<20in=${victoriaPrecip < 20}, Corpus Christi<20in=${corpusPrecip < 20}`);

  if (bothLessThan20) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
